mapper.select:
select t.lc_id,t.lc_id lcId,t.heartbeat_time,t.heartbeat_time heartbeatTime,t.lift_name,t.lift_name
liftName,t.factory_id,t.factory_id factoryId,t.lift_machine_id,t.lift_machine_id
liftMachineId,t.status_cd,t.status_cd statusCd,t.camera_code,t.camera_code
cameraCode,t.community_id,t.community_id communityId,t.camera_name,t.camera_name cameraName,
t.create_time createTime
from lift_camera t
where 1 =1

    and t.lc_id= #{lcId}


    and t.heartbeat_time= #{heartbeatTime}


    and t.lift_name= #{liftName}


    and t.factory_id= #{factoryId}


    and t.lift_machine_id= #{liftMachineId}


    and t.status_cd= #{statusCd}


    and t.camera_code= #{cameraCode}


    and t.community_id= #{communityId}


    and t.camera_name= #{cameraName}

order by t.create_time desc

    limit #{page}, #{row}

